<?php require_once 'config.php';require_login();if(($_SESSION['user']['role']??'')!=='student'){flash('Apenas estudantes podem solicitar sessões de mentoria.','error');header('Location: mentoria.php');exit;}$pdo=db();$id=(int)($_GET['id']??$_POST['service_id']??0);$st=$pdo->prepare("SELECT * FROM servico_mentoria WHERE id=? AND status='published'");$st->execute([$id]);$service=$st->fetch();if(!$service){flash('Serviço não encontrado.','error');header('Location: mentoria.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$date=str_replace('T',' ',$_POST['session_date']??'');$date=str_replace(' ',' ',$date);$message=trim($_POST['message']??'');$dt=DateTime::createFromFormat('Y-m-d H:i',$date);if(!$dt||$dt<=new DateTime()){ $error='Escolhe uma data e hora futuras.';}else{$st=$pdo->prepare("INSERT INTO marcacao_mentoria(student_id,service_id,session_date,message) VALUES(?,?,?,?)");$st->execute([$_SESSION['user']['id'],$id,$dt->format('Y-m-d H:i:s'),$message?:null]);flash('Pedido de mentoria registado. A sessão fica pendente de confirmação.');header('Location: painel.php');exit;}}$page_title='Solicitar mentoria | Kuntima';require 'includes/header.php'; ?>
<section class="form-card"><h1>Solicitar uma sessão</h1><p class="muted"><?=e($service['title'])?> · <?=number_format((float)$service['price'],0,',','.')?> Kz · <?=e($service['duration_minutes'])?> minutos</p><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="service_id" value="<?=$id?>"><div class="field"><label for="session_date">Data e hora pretendidas</label><input type="datetime-local" id="session_date" name="session_date" required></div><div class="field"><label for="message">O que gostarias de trabalhar? (opcional)</label><textarea id="message" name="message" placeholder="Ex.: rever a carta de motivação para uma bolsa."></textarea></div><button class="btn-primary" type="submit">Enviar pedido</button></form><div class="form-foot">O pedido não é uma confirmação de pagamento nem de sessão. A equipa deverá confirmar os detalhes.</div></section><?php require 'includes/footer.php'; ?>
